import os
os.chdir(r'C:/Users/nars7/Downloads/Ideas and Thoughts/Anthro/Anthro.Sim')
def patch(p, pairs):
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (p, a[:100])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8').write(s)

patch('World/Cell.cs', [
("""        /// <summary>The river's warmth: it follows the air slowly (weeks behind).</summary>""",
"""        /// <summary>
        /// A fish weir built across this stretch (0 none, 1 standing). People build it; floods and rot
        /// wear it down unless it's used and mended.
        /// </summary>
        public double Weir;
        /// <summary>The river's warmth: it follows the air slowly (weeks behind).</summary>"""),
("""            if (Wood < WoodCapacity) Wood""",
"""            if (Weir > 0) Weir = Math.Max(0, Weir - 0.003);
            if (Wood < WoodCapacity) Wood"""),
])

patch('Activities/Fishing.cs', [
("""        public static double Efficiency(Person p, bool run)
        {
            var k = p.Knows;
            double e = 0;""",
"""        public static double Efficiency(Person p, bool run) => Efficiency(p, run, null);

        /// <summary>
        /// How well someone fishes here. A weir is a thing built across a particular stretch, not a skill
        /// one carries: it only works where one stands.
        /// </summary>
        public static double Efficiency(Person p, bool run, Cell? spot)
        {
            var k = p.Knows;
            double e = 0;"""),
("""            if (k.Contains("fish.weir")) e = Math.Max(e, run ? 2.5 : 0.8);""",
 """            if (spot != null && spot.Weir >= 0.5) e = Math.Max(e, (run ? 2.5 : 0.8) * spot.Weir);"""),
("""            bool run = spot.FishStock > spot.FishCapacity * 1.5;
            double handling = FishingMethods.Efficiency(P, run) * (0.5 + P.S(Skill.Fishing))""",
 """            bool run = spot.FishStock > spot.FishCapacity * 1.5;
            // Someone who knows how builds a weir across a stretch that has none (a dozen hours' work, more
            // hands make it quicker); one that stands gets mended by whoever fishes there.
            if (P.Knows.Contains("fish.weir") && spot.Weir < 1 && spot.FishCapacity > 0)
            {
                spot.Weir = Math.Min(1, spot.Weir + 0.08 * (0.5 + P.B(BodyTrait.Strength)));
                if (spot.Weir < 0.5) { P.Practice(Skill.Fishing, 0.5); Step = "building a weir"; return; }
            }
            else if (spot.Weir > 0) spot.Weir = Math.Min(1, spot.Weir + 0.02);
            double handling = FishingMethods.Efficiency(P, run, spot) * (0.5 + P.S(Skill.Fishing))"""),
])

