patch('JointActs.cs', [
("""        public double RallyValue(Person p, Household hearth)
        {
            if (p.Home == hearth) return double.NegativeInfinity;
            var rel = RelationTo(p, hearth);
            var owner = hearth.Adults(Clock).OrderByDescending(a => p.GetAffinity(a)).FirstOrDefault();
            double hunger = 1 - (p.Home?.Members.Select(m => m.Satiety).DefaultIfEmpty(1).Min() ?? p.Satiety);
            double plenty = Math.Min(1, Spare(hearth) / Math.Max(1, (p.Home?.Members.Count ?? 1) * 2));
            double anger = AngerAt(p, hearth);
            double defenders = hearth.Adults(Clock).Sum(Might);""",
"""        public double RallyValue(Person p, Household hearth) => RallyValue(p, hearth, FamilyHunger(p));

        /// <summary>How hungry the hungriest of someone's family is.</summary>
        internal static double FamilyHunger(Person p) => 1 - (p.Home?.Members.Select(m => m.Satiety).DefaultIfEmpty(1).Min() ?? p.Satiety);

        internal double RallyValue(Person p, Household hearth, double hunger)
        {
            if (p.Home == hearth) return double.NegativeInfinity;
            var rel = RelationTo(p, hearth);
            var (adults, defenders) = AdultsNow(hearth);
            Person? owner = null;
            double fondest = double.NegativeInfinity, anger = 0;
            foreach (var a in adults)
            {
                double f = p.GetAffinity(a);
                if (f > fondest) { fondest = f; owner = a; }
                double g = p.GetGrievance(a);
                if (g > anger) anger = g;
            }
            double plenty = Math.Min(1, Spare(hearth) / Math.Max(1, (p.Home?.Members.Count ?? 1) * 2));"""),
("""        /// <summary>How hard someone would fight: strength, health, wounds, temper.</summary>""",
"""        // Per-hour caches for decisions (people decide many times an hour; who's grown at a hearth and how
        // strong they are doesn't change within it).
        long _cacheTick = -1;
        readonly Dictionary<Household, (List<Person> adults, double might)> _adultsNow = new Dictionary<Household, (List<Person>, double)>();
        readonly Dictionary<int, Person> _byId = new Dictionary<int, Person>();

        void FreshCaches()
        {
            if (_cacheTick == Clock.Tick) return;
            _cacheTick = Clock.Tick;
            _adultsNow.Clear();
            _byId.Clear();
            foreach (var m in Band.Members) _byId[m.Id] = m;
        }

        /// <summary>A hearth's grown members this hour, and how hard they'd fight together.</summary>
        internal (List<Person> adults, double might) AdultsNow(Household h)
        {
            FreshCaches();
            if (!_adultsNow.TryGetValue(h, out var v))
            {
                var a = h.Adults(Clock).ToList();
                v = (a, a.Sum(Might));
                _adultsNow[h] = v;
            }
            return v;
        }

        /// <summary>A member of this camp by id (this hour), or null.</summary>
        internal Person? MemberById(int id) { FreshCaches(); return _byId.TryGetValue(id, out var p) && Band.Members.Contains(p) ? p : null; }

        /// <summary>How hard someone would fight: strength, health, wounds, temper.</summary>"""),
])

patch('Society.cs', [
("""        public double ConfrontValue(Person p, Person target)
        {
            double anger = p.GetGrievance(target);
            double heat = anger / (anger + 3);
            double fear = Backing(target, p) / Math.Max(0.1, Strength(p)) * 0.3 + p.Injury;""",
"""        public double ConfrontValue(Person p, Person target) => ConfrontValue(p, target, Backing(target, p));

        internal double ConfrontValue(Person p, Person target, double backing)
        {
            double anger = p.GetGrievance(target);
            double heat = anger / (anger + 3);
            double fear = backing / Math.Max(0.1, Strength(p)) * 0.3 + p.Injury;"""),
])

patch('Activities/Decider.cs', [
("""                Person? target = null;
                double anger = 0;
                foreach (var o in band.Members)
                {
                    double g = p.GetGrievance(o) * (1 - o.Injury);   // a beaten man is no longer worth fighting, unless the anger is deep
                    if (g > anger && o != p && Simulation.AwakeInCamp(o)) { anger = g; target = o; }
                }""",
"""                Person? target = null;
                double anger = 0;
                foreach (var kv in p.Grievance)
                {
                    if (kv.Value <= anger) continue;
                    var o = sim.MemberById(kv.Key);
                    if (o == null || o == p) continue;
                    double g = kv.Value * (1 - o.Injury);   // a beaten man is no longer worth fighting, unless the anger is deep
                    if (g > anger && Simulation.AwakeInCamp(o)) { anger = g; target = o; }
                }"""),
("""                    double confront = sim.ConfrontValue(p, target);
                    // Fear of them, and of the kin and friends who'd stand with them.
                    double fear = sim.Backing(target, p) / Math.Max(0.1, p.B(BodyTrait.Strength) * p.Health) * 0.3 + p.Injury;""",
"""                    double backing = sim.Backing(target, p);
                    double confront = sim.ConfrontValue(p, target, backing);
                    // Fear of them, and of the kin and friends who'd stand with them.
                    double fear = backing / Math.Max(0.1, p.B(BodyTrait.Strength) * p.Health) * 0.3 + p.Injury;"""),
("""                    Household? target = null;
                    double best = 0;
                    foreach (var h in band.Households)
                    {
                        if (h == home || Simulation.Spare(h) < 1) continue;
                        double v = sim.RallyValue(p, h);""",
"""                    Household? target = null;
                    double best = 0;
                    double famHunger = Simulation.FamilyHunger(p);
                    foreach (var h in band.Households)
                    {
                        if (h == home || Simulation.Spare(h) < 1) continue;
                        double v = sim.RallyValue(p, h, famHunger);"""),
])
